 Here is a C++ implementation of Dijkstra's algorithm to find the shortest paths from a source vertex to all other vertices in a graph:

```cpp
#include <bits/stdc++.h> 
using namespace std; 

// A structure to represent a directed graph edge
struct Edge { 
    int src, dest, weight; 
}; 

// A structure to represent a connected, directed and 
// weighted graph 
struct Graph { 
    // A list of all edges in the graph 
    vector<Edge> edges; 

    // A list of adjacency lists. 
    vector<list<int>> adjList; 

    // Constructor 
    Graph(int V) { 
        adjList.resize(V); 
    } 

    // Add an edge to the graph 
    void addEdge(int src, int dest, int weight) { 
        Edge edge = {src, dest, weight}; 
        edges.push_back(edge); 

        // Add the edge to adjacency list of src and dest 
        adjList[src].push_back(dest); 
    } 
}; 

// Dijkstra's algorithm 
void dijkstra(Graph& graph, int source) { 
    // Create a priority queue to store vertices that 
    // are being preprocessed. This is weird syntax in C++. 
    // What we want is a min-heap with the vertex/weight pair 
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq; 

    // Create a vector for distances and initialize all 
    // distances as infinite (INF) 
    vector<int> distance(graph.adjList.size(), INT_MAX); 
    distance[source] = 0; 

    // Add source vertex to the priority queue 
    pq.push(make_pair(0, source)); 

    // While priority queue is not empty 
   while (!pq.empty()) { 
        // Extract the vertex with minimum distance 
        int u = pq.top().second; 
        pq.pop(); 

        // Get the list of adjacent vertices of u 
        list<int> neighbours = graph.adjList[u]; 

        // For each adjacent vertex v, if there is a shorter path to v through u. 
        for (auto neighbour : neighbours) { 
            // Get the edge weight from u to v 
            int weight = graph.findEdge(u, neighbour); 

            // If distance to the current vertex is more than the distance through u
            if (distance[neighbour] > distance[u] + weight) { 
                // Updating the distance 
                distance[neighbour] = distance[u] + weight; 

                // Add the current vertex to the priority queue 
                pq.push(make_pair(distance[neighbour], neighbour)); 
            } 
        } 
    } 

    // Print distances 
    printf("Vertex   Distance from Source\n"); 
    for (int i = 0; i < graph.adjList.size(); i++) 
        printf("%d \t\t %d\n", i, distance[i]); 
} 
```

